import{_ as t,H as i,f as r,i as s}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"37 | RESTfulWebServices（1）：明确架构愿景与架构组件间的交互","description":"","frontmatter":{},"headers":[{"level":2,"title":"规划架构愿景","slug":"规划架构愿景","link":"#规划架构愿景","children":[]},{"level":2,"title":"明确架构组件间的交互","slug":"明确架构组件间的交互","link":"#明确架构组件间的交互","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"徐昊·TDD项目实战70讲/37｜RESTfulWebServices（1）：明确架构愿景与架构组件间的交互.md","filePath":"徐昊·TDD项目实战70讲/37｜RESTfulWebServices（1）：明确架构愿景与架构组件间的交互.md","lastUpdated":1795563222000}'),o={name:"徐昊·TDD项目实战70讲/37｜RESTfulWebServices（1）：明确架构愿景与架构组件间的交互.md"};function l(p,e,a,E,n,c){return i(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="_37-restfulwebservices-1-明确架构愿景与架构组件间的交互" tabindex="-1">37 | RESTfulWebServices（1）：明确架构愿景与架构组件间的交互 <a class="header-anchor" href="#_37-restfulwebservices-1-明确架构愿景与架构组件间的交互" aria-label="Permalink to &quot;37 | RESTfulWebServices（1）：明确架构愿景与架构组件间的交互&quot;">​</a></h1><p>你好，我是徐昊。从今天开始，我们就来使用 TDD 的方式实现 RESTful Web Services。</p><p>在上节课，我们展示了需要完成的几大功能块。我们很容易可以发现，RESTful Web Services需要多模块协同完成。而不是像 DI Container 那样，可以从单一模块入手，在完成几个功能之后再进行重构。</p><p>那么我们可以先简单地规划一下架构愿景（Architecture Vision），以简化后续的工作。</p><h2 id="规划架构愿景" tabindex="-1">规划架构愿景 <a class="header-anchor" href="#规划架构愿景" aria-label="Permalink to &quot;规划架构愿景&quot;">​</a></h2><p>首先，我们需要明确的是，我们将以 Servlet 的方式来实现 RESTful Web Services 框架。也就是说，我们将提供一个 Servlet 作为主入口，在其中完成对资源对象（Resources）的派分，并根据不同的超媒体选择对应的 reader 和 writer 进行输入输出处理。大致结构如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/37/1.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/37/1.jpeg" alt=""></a></p><p>然而仅仅如此，还不足以让我们顺滑地进入伦敦学派的流程（如果你足够自信，已经可以开始经典学派 TDD 了），我们需要进一步细化 ResourceServlet 中的组件与交互：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/37/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/37/2.jpeg" alt=""></a></p><p>如上图所示，为大致的组件划分：</p><ul><li><p>ResourceDispatcher 管理所有的 Root Resource，并根据 Root Resource 的标注形成路由表。它可以根据路由表，生产对应的 ResourceLocator。</p></li><li><p>ResourceLocator 表示与 URI 中某一段相匹配的资源方法（Resource Method），并负责调用它。</p></li><li><p>ResourceContext 表示 Resource 上下文，包含所有可注入的组件（通过 @Context 标注）。</p></li><li><p>BodyReader 聚合了所有的 MessageBodyReader，可以根据所需的类型，从HttpServletRequest 中读取对象。</p></li><li><p>BodyWriter 聚合了所有的 MessageBodyWriter，可根据提供的类型，将信息写回到HttpServletResponse 中。</p></li><li><p>ExceptionMapping 聚合了所有的 ExceptionMapper，可根据提供的异常，将信息写回到HttpServletResponse 中。</p></li></ul><p>在构想中，这些组件所对应的交互可能是这样的：</p><ol><li><p>Serlvet 容器调用 ResourceServlet 的 service 方法，并提供 HttpServletRequest 和HttpServletResponse。</p></li><li><p>ResourceServlet 调用 ResourceDispatcher，将所有的 Root Resource 注册到ResourceDispatcher 上。</p></li><li><p>ResourceServlet 调用 ResourceDispatcher 的方法，根据 URI 查找路由表，生成对应的ReosurceLocator 方法。</p></li><li><p>ResourceServlet 调用 ResourceLocator，并提供 ResourceContext、BodyReader、BodyWriter 和 ExceptionMapping。</p></li><li><p>ResourceLocator 根据 Resource Class 的需要，从 ResourceContext 中寻找可注入的组件。初始化 Resource 对象，并完成注入。</p></li><li><p>ResourceLocator 根据 Resource Method 的需要，使用 BodyReader 从HttpServletRequest 中读取信息。</p></li><li><p>ResourceLocator 调用 Resource Method，并通过 BodyWriter 将结果写回HttpServletResponse 中。</p></li><li><p>如果有异常，则使用 ExceptionMapping 将结果写回 HttpServletResponse 中。</p></li></ol><p>如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/37/3.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/37/3.jpeg" alt=""></a></p><p>那么至此我们是否可以开始任务分解了呢？还不行。请回想一下伦敦学派的流程：</p><ul><li><p>按照功能需求与架构愿景划分对象的角色和职责；</p></li><li><p>根据角色与职责，明确对象之间的交互；</p></li><li><p>按照调用栈（Call Stack）的顺序，自外向内依次实现不同的对象；</p></li><li><p>在实现的过程中，依照交互关系，使用测试替身替换所有与被实现对象直接关联的对象；</p></li><li><p>直到所有对象全部实现完成。</p></li></ul><p>所以我们还需要明确对象（架构组件）之间的交互，明确到有清晰的调用栈顺序，足以支撑我们使用测试替身构造测试。</p><h2 id="明确架构组件间的交互" tabindex="-1">明确架构组件间的交互 <a class="header-anchor" href="#明确架构组件间的交互" aria-label="Permalink to &quot;明确架构组件间的交互&quot;">​</a></h2><p>明确架构组件间的交互有三种方法：根据经验设计，通过经典模式进行定向重构，以及Spike。</p><p>根据经验设计永远是一种可能的选项，不过我总觉得这是更难的一种方法（也更为不靠谱）。通过经典模式进行定向重构有个额外的好处，它可以看作是对于架构愿景的验证：通过一组典型场景测试，验证架构的可行性；然后在重构过程中，根据愿景提炼组件间的交互。具体过程和前一个项目差不多，这里可留给你们自己练习。</p><p>Spike 是另一种常用的方法，特别是对遗存代码或需求上下文不够熟悉，不能直接进入经典模式的情况下，经常采用的模式：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/37/4.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/37/4.jpeg" alt=""></a></p><p>Spike 可以看作不严格的经典模式，通常只有非常简单的测试，并不限制一定要用重构，重写也可以。那么以最快的方式理解需求上下文，获得架构愿景就可以了。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>在进入下节课之前，希望你能认真思考如下两个问题。</p><ol><li><p>根据 Spike 的结果，我们要如何调整架构愿景？</p></li><li><p>学完这节课后，你最大的收获是什么？有没有让你特别惊喜的操作？</p></li></ol><p>欢迎把你的想法分享在留言区，也欢迎把你的项目代码的链接分享出来。相信经过你的思考与实操，学习效果会更好！</p>',28)])])}const R=t(o,[["render",l]]);export{h as __pageData,R as default};
